// Forked from the company's Pattern Library (Eleventy 3 + Nunjucks). Owned by the init-proyecto skill since 12.1.0.
// What this build does: walks library/src/patterns/ (GENERATED by scripts/ds-library.py from the design system:
// never edit it), renders one preview per variant and the viewer pages, and bundles the styles into
// assets/css/library.css. The design system's tokens.css and components.css enter through
// src/patterns/_base/base.css (@import), so the previews show the real DS, not a copy.
import { HtmlBasePlugin } from "@11ty/eleventy";
import { buildAssets } from "./lib/assets.js";
import { proposalsMiddleware } from "./lib/proposals-server.js";
import path from "node:path";

export default function (eleventyConfig) {
  // Patterns are rendered from _data/patterns.js, not as standalone pages.
  eleventyConfig.ignores.add("src/patterns/**");
  eleventyConfig.addWatchTarget("./src/patterns/");
  eleventyConfig.addWatchTarget("../design-system/css/");
  eleventyConfig.addWatchTarget("../design-system/tokens/");

  // Viewer CSS/JS (never ships) and the design system's icons and fonts, served under /assets/ds/
  // (the generated templates rewrite the examples' ../assets/ paths to /assets/ds/).
  eleventyConfig.addPassthroughCopy({ "src/assets": "assets" });
  eleventyConfig.addPassthroughCopy({ "../design-system/assets": "assets/ds" });

  // Before every build: bundle the styles and scripts of every component into assets/css/library.css
  // and assets/js/library.js. A compile error fails `npm run build`; while serving it is logged.
  eleventyConfig.on("eleventy.before", async ({ directories, runMode, outputMode }) => {
    if (outputMode !== "fs") return;
    await buildAssets({ outputDir: directories.output, strict: runMode === "build" });
  });
  eleventyConfig.addGlobalData("hostCss", "");

  // Solo con `npm start`: el botón «Editar» de la ficha guarda propuestas en design-system/proposals/.
  // Publicado como web estática no hay servidor y el botón descarga la propuesta.
  eleventyConfig.setServerOptions({ middleware: [proposalsMiddleware(path.resolve(".."))] });
  eleventyConfig.addWatchTarget("../design-system/proposals/");
  // La home es un tablero que lee contratos, informes, volcados y ciclo de vida en cada build (src/_data/dashboard.js).
  eleventyConfig.addWatchTarget("../design-system/schemas/");
  eleventyConfig.addWatchTarget("../design-system/reports/");
  eleventyConfig.addWatchTarget("../design-system/sync/");

  // Rewrites URLs when published in a subfolder (--pathprefix=/library/).
  eleventyConfig.addPlugin(HtmlBasePlugin);

  return {
    dir: { input: "src", includes: "_viewer", data: "_data", output: "_site" },
    markdownTemplateEngine: "njk",
    htmlTemplateEngine: "njk",
  };
}
